private void SpawnFood(GameObject foodOBJ)
{
    //delete items on plates when food is spawned
    Destroy(plate1.HeldItem.gameObject);
    Destroy(plate2.HeldItem.gameObject);
    Destroy(plate3.HeldItem.gameObject);
    Destroy(plate4.HeldItem.gameObject);

    //make sure they are deleted
    plate1.HeldItem = null;
    plate2.HeldItem = null;
    plate3.HeldItem = null;
    plate4.HeldItem = null;

    //spawn the food
    Instantiate(foodOBJ, foodTransform.position, foodTransform.rotation);
}

IEnumerator SpawnWaves()
{
    for (int wave = 1; wave <= totalWaves; wave++, waveCount++) // Go through each wave
    {
        // Spawn the enemies for this wave
        for (int i = 0; i < enemiesPerWave; i++)
        {
            SpawnEnemy(); // This spawns one enemy
            yield return new WaitForSeconds(timeBetweenEnemies); // Wait for 1 second before spawning the next one
        }
        //all enemies spawned

        yield return new WaitForSeconds(timeBetweenWaves); // Wait for 5 seconds before starting the next wave
        //all waves finished

    }

    //all waves complete
}

// This function actually spawns the enemy at the spawn point
void SpawnEnemy()
{
    int ghost = Random.Range(1, 5);
    //choose which ghost to spawn
    switch (ghost)
    {
        case 1:
            ChosenGhost = enemyPrefab1;
            break;
        case 2:
            ChosenGhost = enemyPrefab2;
            break;
        case 3:
            ChosenGhost = enemyPrefab3;
            break;
        case 4:
            ChosenGhost = enemyPrefab4;
            break;
    }

    int randomLoc = Random.Range(1, 6);
    Debug.Log(randomLoc);
    //choose which location to spawn at
    switch (randomLoc)
    {
        case 1:
            newLoc = loc1;
            break;
        case 2:
            newLoc = loc2;
            break;
        case 3:
            newLoc = loc3;
            break;
        case 4:
            newLoc = loc4;
            break;
        case 5:
            newLoc = loc5;
            break;
    }

    if (ChosenGhost != null)
    {
        //spawn chosen ghost at the randomly chosen location
        spawnedGhost = Instantiate(ChosenGhost, newLoc.position, Quaternion.identity);
    }

    //depending on which wave is the current one, increase the spawned ghost health
    health increasedHP = spawnedGhost.GetComponentInChildren<health>();
    increasedHP.maxHealth = 40f + (waveCount - 1) * 20;
}

private void Update()
{
    timer += Time.deltaTime;
    if (WalkEnabled == true)
    {
        //keep playing the walking feeling when player is walking
        if (isWalkingHaptic == false)
        {
            //play walking feeling when walking
            BhapticsLibrary.Play(BhapticsEvent.SHORTWALK);
            isWalkingHaptic = true;
            timer = 0f;
        }

        if (isWalkingHaptic == true && timer > 0.6f)
        {
            //if the walking feeling has stopped but the player is still moving in game
            //stop the walking haptic bool so that the walking feeling can be played again
            isWalkingHaptic = false;
        }
    }
    if (WalkEnabled == false)
    {
        //stop the walking feeling if the player suddenly stops moving
        BhapticsLibrary.StopByEventId("WALKING");
    }
}

private void actionPerformed(InputAction.CallbackContext context)
{
    Vector2 input = context.ReadValue<Vector2>();

    //check the stick movement
    //depending on that decide if player is walking or not
    if (input.magnitude < 0.9f)
    {
        //not walking
        WalkEnabled = false;
    }
    else if (input.magnitude > 0.9f)
    {
        //player is walking
        WalkEnabled = true;
    }
}

protected override void Update()
{
    speed = 2f;

    if (projectilesTransform != null)
    {
        //check if the tray frisbee is already arrived back at its spawn location and then despawn it
        if (movingBack == true && transform.position == projectilesTransform.position)
        {
            Destroy(this.gameObject, 0.5f);
        }
        //if the tray frisbee has reached the old marked position of the player move it back
        if ((Tray.transform.position == oldPlayerTransform && movingBack == false) || movingBack == true)
        {
            movingBack = true;
            Tray.transform.position = Vector3.MoveTowards(Tray.transform.position, projectilesTransform.transform.position, speed * Time.deltaTime);
        }
        //otherwise move the tray frisbee towards the old player transform
        else
        {
            Tray.transform.position = Vector3.MoveTowards(Tray.transform.position, oldPlayerTransform, speed * Time.deltaTime);
        }
    }
}
